mapper.select:
SELECT li.factory_code AS factoryCode, li.login_id AS id, ui.user_nm AS name, li.password_hash AS password, NULL AS ihidNum, ui.email_adres AS email, CASE WHEN li.authority_code = 'PLATFORM_ADMIN' THEN 'ADM' ELSE 'USR' END AS userSe, ui.department_id AS orgnztId, ui.esntl_id AS uniqId, ui.department_id AS groupId, di.department_code AS groupCode, CASE WHEN li.authority_code = 'PLATFORM_ADMIN' THEN 'ROLE_ADMIN' WHEN li.authority_code = 'TENANT_ADMIN' THEN 'ROLE_TENANT_ADMIN' ELSE 'ROLE_USER' END AS groupNm, li.authority_code AS roleCode FROM TB_LoginInfo li JOIN TB_UserInfo ui ON ui.user_id = li.user_id AND ui.factory_code = li.factory_code LEFT JOIN TB_DepartmentInfo di ON di.department_id = ui.department_id AND di.factory_code = ui.factory_code WHERE li.login_id = #{id} AND li.password_hash = #{password} AND li.factory_code = #{factoryCode}
AND li.authority_code = #{roleCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(ui.use_at, 'Y') = 'Y' AND COALESCE(di.use_at, 'Y') = 'Y'

SELECT li.login_id AS id FROM TB_LoginInfo li JOIN TB_UserInfo ui ON ui.user_id = li.user_id AND ui.factory_code = li.factory_code WHERE ui.user_nm = #{name} AND ui.email_adres = #{email}
AND li.factory_code = #{factoryCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(ui.use_at, 'Y') = 'Y' ORDER BY li.created_at DESC LIMIT 1

SELECT li.password_hash AS password FROM TB_LoginInfo li JOIN TB_UserInfo ui ON ui.user_id = li.user_id AND ui.factory_code = li.factory_code WHERE li.login_id = #{id} AND ui.user_nm = #{name} AND ui.email_adres = #{email}
AND li.factory_code = #{factoryCode}
AND COALESCE(li.use_at, 'Y') = 'Y' AND COALESCE(ui.use_at, 'Y') = 'Y'
